import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import api from '../services/api';

const RestablecerPassword = () => {
  const { token } = useParams();
  const navigate = useNavigate();
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [tokenValido, setTokenValido] = useState(false);
  const [verificando, setVerificando] = useState(true);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  useEffect(() => {
    verificarToken();
  }, [token]);

  const verificarToken = async () => {
    try {
      const response = await api.get(`/password/verificar/${token}`);
      if (response.data.success) {
        setTokenValido(true);
      } else {
        setError(response.data.message || 'Token inválido');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'El enlace de recuperación es inválido o ha expirado');
    } finally {
      setVerificando(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    setError('');

    if (password !== confirmPassword) {
      setError('Las contraseñas no coinciden');
      setLoading(false);
      return;
    }

    if (password.length < 6) {
      setError('La contraseña debe tener al menos 6 caracteres');
      setLoading(false);
      return;
    }

    try {
      const response = await api.post('/password/restablecer', { token, password });
      setMessage(response.data.message);
      setTimeout(() => {
        navigate('/login');
      }, 3000);
    } catch (err) {
      setError(err.response?.data?.message || 'Error al restablecer la contraseña');
    } finally {
      setLoading(false);
    }
  };

  if (verificando) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8fafc]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00643c] mx-auto mb-4"></div>
          <p className="text-[#45474c]">Verificando enlace...</p>
        </div>
      </div>
    );
  }

  if (!tokenValido && error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8fafc] px-4">
        <div className="bg-white w-full max-w-md rounded-xl p-8 border border-[#bec9bf] shadow-lg text-center">
          <div className="mb-4 text-red-500">
            <span className="material-symbols-outlined text-5xl">error</span>
          </div>
          <h2 className="text-xl font-bold text-[#0b1c30] mb-2">Enlace inválido</h2>
          <p className="text-[#45474c] mb-6">{error}</p>
          <Link to="/recuperar-password" className="text-[#00643c] font-bold hover:underline">
            Solicitar nuevo enlace
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f8fafc] px-4">
      <div className="bg-white w-full max-w-md rounded-xl p-8 border border-[#bec9bf] shadow-lg">
        <div className="flex flex-col items-center mb-8">
          <img src="/logosena.png" alt="Logo SENA" className="w-24 h-24 mb-4 object-contain" />
          <h1 className="text-2xl font-bold text-[#00643c] text-center">Restablecer Contraseña</h1>
          <p className="text-sm text-[#45474c] text-center mt-2">
            Ingresa tu nueva contraseña
          </p>
        </div>

        {message && (
          <div className="mb-4 p-3 rounded-lg bg-green-100 text-green-700 text-center text-sm">
            {message}
          </div>
        )}
        
        {error && (
          <div className="mb-4 p-3 rounded-lg bg-red-100 text-red-700 text-center text-sm">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-[#3f4942] mb-1">
              Nueva contraseña
            </label>
            <div className="relative">
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="w-full px-4 py-2 pr-10 border border-[#bec9bf] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#00643c] focus:border-transparent"
                placeholder="********"
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-[#6f7a71]"
              >
                <span className="material-symbols-outlined text-sm">
                  {showPassword ? 'visibility_off' : 'visibility'}
                </span>
              </button>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-[#3f4942] mb-1">
              Confirmar contraseña
            </label>
            <div className="relative">
              <input
                type={showConfirmPassword ? 'text' : 'password'}
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                required
                className="w-full px-4 py-2 pr-10 border border-[#bec9bf] rounded-lg focus:outline-none focus:ring-2 focus:ring-[#00643c] focus:border-transparent"
                placeholder="********"
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-[#6f7a71]"
              >
                <span className="material-symbols-outlined text-sm">
                  {showConfirmPassword ? 'visibility_off' : 'visibility'}
                </span>
              </button>
            </div>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-[#00643c] text-white font-bold py-3 rounded-lg hover:bg-[#004a2b] transition-all disabled:opacity-70"
          >
            {loading ? 'Restableciendo...' : 'Restablecer contraseña'}
          </button>

          <div className="text-center">
            <Link to="/login" className="text-sm text-[#00643c] hover:underline">
              Volver al inicio de sesión
            </Link>
          </div>
        </form>
      </div>
    </div>
  );
};

export default RestablecerPassword;
